Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fs/ntfs3: fix missing run load for vcn0 in
 attr_data_get_block_locked()

When a compressed or sparse attribute has its clusters frame-aligned,
vcn is rounded down to the frame start using cmask, which can result
in vcn != vcn0. In this case, vcn and vcn0 may reside in different
attribute segments.

The code already handles the case where vcn is in a different segment
by loading its runs before allocation. However, it fails to load runs
for vcn0 when vcn0 resides in a different segment than vcn. This causes
run_lookup_entry() to return SPARSE_LCN for vcn0 since its segment was
never loaded into the in-memory run list, triggering the WARN_ON(1).

Fix this by adding a missing check for vcn0 after the existing vcn
segment check. If vcn0 falls outside the current segment range
[svcn, evcn1), find and load the attribute segment containing vcn0
before performing the run lookup.

The following scenario triggers the bug:
  attr_data_get_block_locked()
    vcn = vcn0 & cmask        <- vcn != vcn0 after frame alignment
    load runs for vcn segment <- vcn0 segment not loaded!
    attr_allocate_clusters()  <- allocation succeeds
    run_lookup_entry(vcn0)    <- vcn0 not in run -> SPARSE_LCN
    WARN_ON(1)                <- bug fires here!

Reported-by: syzbot+c1e9aedbd913fadad617@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=c1e9aedbd913fadad617
Fixes: c380b52f6c57 ("fs/ntfs3: Change new sparse cluster processing")
Signed-off-by: Deepanshu Kartikey <Kartikey406@gmail.com>
Signed-off-by: Konstantin Komarov <almaz.alexandrovich@paragon-software.com>

Here is the root cause:
When a compressed or sparse attribute's clusters are frame-aligned, vcn is rounded down to the frame start, potentially differing from vcn0. The code loads runs for the segment containing vcn but fails to load runs for vcn0 when it resides in a different attribute segment. This causes run_lookup_entry(vcn0) to incorrectly return SPARSE_LCN, triggering a WARN_ON(1) during allocation.

Here is the patch:
  */
 int attr_data_get_block_locked(struct ntfs_inode *ni, CLST vcn, CLST clen,
 			       CLST *lcn, CLST *len, bool *new, bool zero,
 			       void **res, bool no_da)
 {
 	int err = 0;
 	struct ntfs_sb_info *sbi = ni->mi.sbi;
 	struct runs_tree *run = &ni->file.run;
 	struct runs_tree *run_da = &ni->file.run_da;
 	bool da = sbi->options->delalloc && !no_da;
 	u8 cluster_bits;
 	struct ATTRIB *attr, *attr_b;
 	struct ATTR_LIST_ENTRY *le, *le_b;
 	struct mft_inode *mi, *mi_b;
 	CLST hint, svcn, to_alloc, evcn1, next_svcn, asize, end, vcn0;
 	CLST alloc, evcn;
 	unsigned fr;
 	u64 total_size, total_size0;
 	int step;

 again:
 	if (da && run_lookup_entry(run_da, vcn, lcn, len, NULL)) {
 		/* The requested vcn is delay allocated. */
 		*lcn = DELALLOC_LCN;
 	} else if (run_lookup_entry(run, vcn, lcn, len, NULL)) {
 		/* The requested vcn is known in current run. */
 	} else {
 		*len = 0;
 	}

 	if (*len) {
 		if (*lcn != SPARSE_LCN || !new)
 			goto out; /* normal way without allocation. */
 		if (clen > *len)
 			clen = *len;
 	}

 	cluster_bits = sbi->cluster_bits;
 	step = 0;

 	le_b = NULL;
 	attr_b = ni_find_attr(ni, NULL, &le_b, ATTR_DATA, NULL, 0, NULL, &mi_b);
 	if (!attr_b) {
 		err = -ENOENT;
 		goto out;
 	}

 	if (!attr_b->non_res) {
 		u32 data_size = le32_to_cpu(attr_b->res.data_size);
 		*lcn = RESIDENT_LCN;
 		*len = data_size;
 		if (res && data_size) {
 			*res = kmemdup(resident_data(attr_b), data_size,
 				       GFP_KERNEL);
 			if (!*res)
 				err = -ENOMEM;
 		}
 		goto out;
 	}

 	asize = le64_to_cpu(attr_b->nres.alloc_size) >> cluster_bits;
 	if (vcn >= asize) {
 		if (new) {
 			err = -EINVAL;
 		} else {
 			*len = 1;
 			*lcn = EOF_LCN;
 		}
 		goto out;
 	}

 	svcn = le64_to_cpu(attr_b->nres.svcn);
 	evcn1 = le64_to_cpu(attr_b->nres.evcn) + 1;

 	attr = attr_b;
 	le = le_b;
 	mi = mi_b;

 	if (le_b && (vcn < svcn || evcn1 <= vcn)) {
 		attr = ni_find_attr(ni, attr_b, &le, ATTR_DATA, NULL, 0, &vcn,
 				    &mi);
 		if (!attr) {
 			err = -EINVAL;
 			goto out;
 		}
 		svcn = le64_to_cpu(attr->nres.svcn);
 		evcn1 = le64_to_cpu(attr->nres.evcn) + 1;
 	}

 	/* Load in cache actual information. */
 	err = attr_load_runs(attr, ni, run, NULL);
 	if (err)
 		goto out;

 	/* Check for compressed frame. */
 	err = attr_is_frame_compressed(ni, attr_b, vcn >> NTFS_LZNT_CUNIT,
 				       &hint, run);
 	if (err)
 		goto out;

 	if (hint) {
 		/* if frame is compressed - don't touch it. */
 		*lcn = COMPRESSED_LCN;
 		/* length to the end of frame. */
 		*len = NTFS_LZNT_CLUSTERS - (vcn & (NTFS_LZNT_CLUSTERS - 1));
 		err = 0;
 		goto out;
 	}

 	if (!*len) {
 		if (run_lookup_entry(run, vcn, lcn, len, NULL)) {
 			if (*lcn != SPARSE_LCN || !new)
 				goto ok; /* Slow normal way without allocation. */

 			if (clen > *len)
 				clen = *len;
 		} else if (!new) {
 			/* Here we may return -ENOENT.
 			 * In any case caller gets zero length. */
 			goto ok;
 		}
 	}

 	if (!is_attr_ext(attr_b)) {
 		/* The code below only for sparsed or compressed attributes. */
 		err = -EINVAL;
 		goto out;
 	}

 	vcn0 = vcn;
 	to_alloc = clen;
 	fr = (sbi->record_size - le32_to_cpu(mi->mrec->used) + 8) / 3 + 1;
 	/* Allocate frame aligned clusters.
 	 * ntfs.sys usually uses 16 clusters per frame for sparsed or compressed.
 	 * ntfs3 uses 1 cluster per frame for new created sparsed files. */
 	if (attr_b->nres.c_unit) {
 		CLST clst_per_frame = 1u << attr_b->nres.c_unit;
 		CLST cmask = ~(clst_per_frame - 1);

 		/* Get frame aligned vcn and to_alloc. */
 		vcn = vcn0 & cmask;
 		to_alloc = ((vcn0 + clen + clst_per_frame - 1) & cmask) - vcn;
 		if (fr < clst_per_frame)
 			fr = clst_per_frame;
 		if (vcn != vcn0)
 			zero = true;

 		/* Check if 'vcn' and 'vcn0' in different attribute segments. */
 		if (vcn < svcn || evcn1 <= vcn) {
 			struct ATTRIB *attr2;
 			/* Load runs for truncated vcn. */
 			attr2 = ni_find_attr(ni, attr_b, &le_b, ATTR_DATA, NULL,
 					     0, &vcn, &mi);
 			if (!attr2) {
 				err = -EINVAL;
 				goto out;
 			}
 			evcn1 = le64_to_cpu(attr2->nres.evcn) + 1;
 			err = attr_load_runs(attr2, ni, run, NULL);
 			if (err)
 				goto out;
 		}
+
+		if (vcn0 < svcn || evcn1 <= vcn0) {
+			struct ATTRIB *attr2;
+
+			attr2 = ni_find_attr(ni, attr_b, &le_b, ATTR_DATA, NULL,
+					       0, &vcn0, &mi);
+			if (!attr2) {
+				err = -EINVAL;
+				goto out;
+			}
+			err = attr_load_runs(attr2, ni, run, NULL);
+			if (err)
+				goto out;
+		}
+
 		da = false; /* no delalloc for compressed file. */
 	}

 	if (vcn + to_alloc > asize)
 		to_alloc = asize - vcn;

 	if (da) {
 		CLST rlen1, rlen2;
 		if (!ntfs_check_free_space(sbi, to_alloc, 0, true)) {
 			err = ni_allocate_da_blocks_locked(ni);
 			if (err)
 				goto out;
 			/* Layout of records may be changed. Start again without 'da'. */
 			da = false;
 			goto again;
 		}

 		/* run_add_entry consolidates existed ranges. */
 		rlen1 = run_len(run_da);
 		if (!run_add_entry(run_da, vcn, SPARSE_LCN, to_alloc, false)) {
 			err = -ENOMEM;
 			goto out;
 		}
 		rlen2 = run_len(run_da);

 		/* new added delay clusters = rlen2 - rlen1. */
 		ntfs_add_da(sbi, rlen2 - rlen1);
 		*len = to_alloc;
 		*lcn = DELALLOC_LCN;
 		goto ok;
 	}

 	/* Get the last LCN to allocate from. */
 	hint = 0;

 	if (vcn > evcn1) {
 		if (!run_add_entry(run, evcn1, SPARSE_LCN, vcn - evcn1,
 				   false)) {
 			err = -ENOMEM;
 			goto out;
 		}
 	} else if (vcn && !run_lookup_entry(run, vcn - 1, &hint, NULL, NULL)) {
 		hint = -1;
 	}

 	/* Allocate and zeroout new clusters. */
 	err = attr_allocate_clusters(sbi, run, run_da, vcn, hint + 1, to_alloc,
 				     NULL,
 				     zero ? ALLOCATE_ZERO : ALLOCATE_ONE_FR,
 				     len, fr, lcn, len);
 	if (err)
 		goto out;
 	*new = true;
 	step = 1;

 	end = vcn + *len;
 	/* Save 'total_size0' to restore if error. */
 	total_size0 = le64_to_cpu(attr_b->nres.total_size);
 	total_size = total_size0 + ((u64)*len << cluster_bits);

 	if (vcn != vcn0) {
 		if (!run_lookup_entry(run, vcn0, lcn, len, NULL)) {
 			err = -EINVAL;
 			goto out;
 		}
 		if (*lcn == SPARSE_LCN) {
 			/* Internal error. Should not happened. */
 			WARN_ON(1);
 			err = -EINVAL;
 			goto out;
 		}
 		/* Check case when vcn0 + len overlaps new allocated clusters. */
 		if (vcn0 + *len > end)
 			*len = end - vcn0;
 	}

 repack:
 	err = mi_pack_runs(mi, attr, run, max(end, evcn1) - svcn);
 	if (err)
 		goto out;

 	attr_b->nres.total_size = cpu_to_le64(total_size);
 	inode_set_bytes(&ni->vfs_inode, total_size);
 	ni->ni_flags |= NI_FLAG_UPDATE_PARENT;

 	mi_b->dirty = true;
 	mark_inode_dirty(&ni->vfs_inode);

 	/* Stored [vcn : next_svcn) from [vcn : end). */
 	next_svcn = le64_to_cpu(attr->nres.evcn) + 1;

 	if (end <= evcn1) {
 		if (next_svcn == evcn1) {
 			/* Normal way. Update attribute and exit. */
 			goto ok;
 		}
 		/* Add new segment [next_svcn : evcn1 - next_svcn). */
 		if (!ni->attr_list.size) {
 			err = ni_create_attr_list(ni);
 			if (err)
 				goto undo1;
 			/* Layout of records is changed. */
 			le_b = NULL;
 			attr_b = ni_find_attr(ni, NULL, &le_b, ATTR_DATA, NULL,
 					      0, NULL, &mi_b);
 			if (!attr_b) {
 				err = -ENOENT;
 				goto out;
 			}

 			attr = attr_b;
 			le = le_b;
 			mi = mi_b;
 			goto repack;
 		}
 	}

 	/*
 	 * The code below may require additional cluster (to extend attribute list)
 	 * and / or one MFT record
 	 * It is too complex to undo operations if -ENOSPC occurs deep inside
 	 * in 'ni_insert_nonresident'.
 	 * Return in advance -ENOSPC here if there are no free cluster and no free MFT.
 	 */
 	if (!ntfs_check_free_space(sbi, 1, 1, false)) {
 		/* Undo step 1. */
 		err = -ENOSPC;
 		goto undo1;
 	}

 	step = 2;
 	svcn = evcn1;

 	/* Estimate next attribute. */
 	attr = ni_find_attr(ni, attr, &le, ATTR_DATA, NULL, 0, &svcn, &mi);

 	if (!attr) {
 		/* Insert new attribute segment. */
 		goto ins_ext;
 	}

 	/* Try to update existed attribute segment. */
 	alloc = bytes_to_cluster(sbi, le64_to_cpu(attr_b->nres.alloc_size));
 	evcn = le64_to_cpu(attr->nres.evcn);

 	if (end < next_svcn)
 		end = next_svcn;
 	while (end > evcn) {
 		/* Remove segment [svcn : evcn). */
 		mi_remove_attr(NULL, mi, attr);

 		if (!al_remove_le(ni, le)) {
 			err = -EINVAL;
 			goto out;
 		}

 		if (evcn + 1 >= alloc) {
 			/* Last attribute segment. */
 			evcn1 = evcn + 1;
 			goto ins_ext;
 		}

 		if (ni_load_mi(ni, le, &mi)) {
 			attr = NULL;
 			goto out;
 		}

 		attr = mi_find_attr(ni, mi, NULL, ATTR_DATA, NULL, 0, &le->id);
 		if (!attr) {
 			err = -EINVAL;
 			goto out;
 		}
 		svcn = le64_to_cpu(attr->nres.svcn);
 		evcn = le64_to_cpu(attr->nres.evcn);
 	}

 	if (end < svcn)
 		end = svcn;

 	err = attr_load_runs(attr, ni, run, &end);
 	if (err)
 		goto out;

 	evcn1 = evcn + 1;
 	attr->nres.svcn = cpu_to_le64(next_svcn);
 	err = mi_pack_runs(mi, attr, run, evcn1 - next_svcn);
 	if (err)
 		goto out;

 	le->vcn = cpu_to_le64(next_svcn);
 	ni->attr_list.dirty = true;
 	mi->dirty = true;
 	next_svcn = le64_to_cpu(attr->nres.evcn) + 1;

 ins_ext:
 	if (evcn1 > next_svcn) {
 		err = ni_insert_nonresident(ni, ATTR_DATA, NULL, 0, run,
 					    next_svcn, evcn1 - next_svcn,
 					    attr_b->flags, &attr, &mi, NULL);
 		if (err)
 			goto out;
 	}
 ok:
 	run_truncate_around(run, vcn);
 out:
 	if (err && step > 1) {
 		/* Too complex to restore. */
 		_ntfs_bad_inode(&ni->vfs_inode);
 	}

 	return err;

 undo1:
 	/* Undo step1. */
 	attr_b->nres.total_size = cpu_to_le64(total_size0);
 	inode_set_bytes(&ni->vfs_inode, total_size0);

 	if (run_deallocate_ex(sbi, run, vcn, *len, NULL, false, run_da) ||
 	    !run_add_entry(run, vcn, SPARSE_LCN, *len, false) ||
 	    mi_pack_runs(mi, attr, run, max(end, evcn1) - svcn)) {
 		_ntfs_bad_inode(&ni->vfs_inode);
 	}
 	goto out;
 }



